#include <stdio.h>

int main() {
  int fahr;

  printf("Fahrenheit  Celsius  using 5 / 9\n");
  for (fahr = 0; fahr <= 100; fahr += 20) {
    double celsius = (5.0 / 9.0) * (fahr - 32);   /* 5.0 has a decimal point, so this works */
    int broken = 5 / 9 * (fahr - 32);              /* 5 / 9 is 0 in whole numbers, so this is always 0 */
    printf("%10d %8.1f %8d\n", fahr, celsius, broken);
  }

  /* Every C type has a fixed size, counted in bytes (8 bits each). */
  printf("\nA char is %d byte\n", (int)sizeof(char));
  printf("An int is %d bytes\n", (int)sizeof(int));
  printf("A double is %d bytes\n", (int)sizeof(double));
  return 0;
}

#include <stdio.h>

/* Each topping gets its own bit. */
#define CHEESE    1   /* 0001 */
#define TOMATO    2   /* 0010 */
#define MUSHROOM  4   /* 0100 */
#define PINEAPPLE 8   /* 1000 */

void show(const char *step, int order) {
  int bit;
  printf("%-22s ", step);
  for (bit = 3; bit >= 0; bit--) printf("%d", (order >> bit) & 1);   /* >> moves a bit to the end */
  printf(" = %2d   pineapple:%s\n", order, (order & PINEAPPLE) ? "yes" : "no");
}

int main() {
  int order = CHEESE | TOMATO;          /* |  switches bits on  */
  show("cheese and tomato", order);
  order = order | PINEAPPLE;
  show("add pineapple", order);
  order = order & ~TOMATO;              /* & ~ switches one off */
  show("hold the tomato", order);
  order = order ^ MUSHROOM;             /* ^  flips a bit       */
  show("flip mushroom", order);
  return 0;
}

#include <stdio.h>

#define RULE  30    /* try 90, 110 or 150 */
#define WIDTH 63
#define STEPS 32

int main() {
  int cells[WIDTH];
  int next[WIDTH];
  int i, step;

  for (i = 0; i < WIDTH; i++) cells[i] = 0;   /* C doesn't clear memory for you */
  cells[WIDTH / 2] = 1;

  printf("__NB_SET__ {\"key\":\"ca_rule\",\"value\":%d}\n", RULE);
  printf("__NB_SET__ {\"key\":\"ca_rows\",\"value\":[");
  for (step = 0; step < STEPS; step++) {
    printf(step ? ",\"" : "\"");
    for (i = 0; i < WIDTH; i++) printf("%c", cells[i] ? '#' : '.');
    printf("\"");

    for (i = 0; i < WIDTH; i++) {
      int left = cells[(i + WIDTH - 1) % WIDTH];
      int right = cells[(i + 1) % WIDTH];
      int pattern = left * 4 + cells[i] * 2 + right;   /* three cells make a number 0 to 7 */
      next[i] = (RULE >> pattern) & 1;                 /* that bit of RULE is the answer   */
    }
    for (i = 0; i < WIDTH; i++) cells[i] = next[i];
  }
  printf("]}\n");

  printf("Rule %d: %d rows of %d cells sent to nb.ca_rows\n", RULE, STEPS, WIDTH);
  return 0;
}
